-- EN01 run and evidence store (generated by v3_store.ddl(); do not edit by hand).
-- Run once in Snowsight as the role that owns the Cortex lab app (WBR_OWNER).
-- The app only INSERTs and SELECTs; it never creates or alters these objects.
-- In Snowsight use Run All (Ctrl+Shift+Enter); every statement is safe to re-run.

USE ROLE WBR_OWNER;

CREATE SCHEMA IF NOT EXISTS WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE COMMENT = 'Tableau to SiS accelerator: run and evidence store (EN01)';

CREATE TABLE IF NOT EXISTS WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.RUNS (
  RUN_ID STRING,
  STARTED_AT TIMESTAMP_TZ,
  STARTED_BY STRING,
  SNOWFLAKE_USER STRING,
  APP_IDENTIFIER STRING,
  APP_BUILD_SHA256 STRING,
  ENGINE_VERSION STRING,
  WORKBOOK_NAME STRING,
  ORIGIN STRING,
  SOURCE_REF STRING,
  WORKBOOK_SHA256 STRING
) COMMENT = 'One row per migration run; written with the first saved step of the run';

CREATE TABLE IF NOT EXISTS WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.RUN_EVENTS (
  RUN_ID STRING,
  EVENT_NO NUMBER,
  RECORDED_AT TIMESTAMP_TZ,
  STAGE STRING,
  TITLE STRING,
  KIND STRING,
  DETAIL STRING
) COMMENT = 'Run log, one row per event; written at the end of each stage and after each action';

CREATE TABLE IF NOT EXISTS WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.RUN_SNAPSHOTS (
  RUN_ID STRING,
  SNAPSHOT_NO NUMBER,
  PART_NO NUMBER,
  PARTS NUMBER,
  SNAPSHOT_AT TIMESTAMP_TZ,
  REASON STRING,
  SAVED_BY STRING,
  STATES VARIANT,
  FAILED_STAGE STRING,
  BYTES NUMBER,
  SHA256 STRING,
  CONTENT_GZ_B64 STRING
) COMMENT = 'Saved run state used to reopen a run; part 0 is written last, so a snapshot with part 0 is complete';

CREATE TABLE IF NOT EXISTS WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.SHEET_RESULTS (
  RUN_ID STRING,
  PASS_NO NUMBER,
  RECORDED_AT TIMESTAMP_TZ,
  SHEET STRING,
  SUPPORT_STATE STRING,
  STATUS STRING,
  MATCHED_VALUES NUMBER,
  MISMATCHED_VALUES NUMBER,
  ROWS_MISSING_IN_APP NUMBER,
  NOTE STRING,
  FIX_APPLIED STRING,
  REFERENCE STRING,
  SUMMARY VARIANT,
  DIFFERENCES VARIANT
) COMMENT = 'Each sheet''s comparison with Tableau; a new PASS_NO each time validation results change';

CREATE TABLE IF NOT EXISTS WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.SHEET_RENDERS (
  RUN_ID STRING,
  PASS_NO NUMBER,
  RECORDED_AT TIMESTAMP_TZ,
  DASHBOARD STRING,
  SHEET STRING,
  KIND STRING,
  ENGINE_STATE STRING,
  RENDERS STRING,
  ROWS_DRAWN NUMBER,
  OUTPUT STRING,
  NOTE STRING,
  MESSAGES STRING
) COMMENT = 'Whether each sheet draws on Snowflake (every run); a new PASS_NO when the results change';

CREATE TABLE IF NOT EXISTS WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.CORTEX_CALLS (
  RUN_ID STRING,
  CALL_NO NUMBER,
  CALLED_AT TIMESTAMP_TZ,
  STAGE STRING,
  PURPOSE STRING,
  FUNCTION STRING,
  MODEL STRING,
  STATUS STRING,
  ELAPSED_MS NUMBER,
  INPUT_TOKENS NUMBER,
  OUTPUT_TOKENS NUMBER,
  TOKEN_SOURCE STRING,
  AI_CREDITS FLOAT,
  COST_USD FLOAT,
  RATE_BASIS STRING,
  NOTE STRING,
  PROMPT_SHA256 STRING,
  RESPONSE VARIANT
) COMMENT = 'One row per Cortex call: model, status, tokens and cost; failures keep the exception class only';

CREATE TABLE IF NOT EXISTS WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.CORTEX_PROPOSALS (
  RUN_ID STRING,
  PROPOSAL_NO NUMBER,
  RECORDED_AT TIMESTAMP_TZ,
  STAGE STRING,
  KIND STRING,
  SUBJECT STRING,
  PROPOSAL VARIANT,
  CODE_CHECK STRING,
  CODE_VERDICT STRING,
  PASSED_CODE_CHECK BOOLEAN,
  CHANGES_APP BOOLEAN,
  EVIDENCE VARIANT
) COMMENT = 'What Cortex proposed and code''s ruling; a new row when the ruling or its use changes';

CREATE TABLE IF NOT EXISTS WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.PROOFS (
  RUN_ID STRING,
  PROOF_NO NUMBER,
  PROOF_KEY STRING,
  RECORDED_AT TIMESTAMP_TZ,
  SHEET STRING,
  HYPOTHESIS_ID STRING,
  HYPOTHESIS STRING,
  CORTEX_RANK STRING,
  CORTEX_REASON STRING,
  TEST STRING,
  RESULT STRING,
  EVIDENCE STRING,
  FIX_KEY STRING,
  TESTED_SQL STRING,
  ENGINE_SQL STRING,
  CONCLUSION STRING
) COMMENT = 'Cause proof: one row per hypothesis tested by code with a read-only query';

CREATE TABLE IF NOT EXISTS WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.APPROVALS (
  RUN_ID STRING,
  APPROVAL_ID STRING,
  APPROVED_AT TIMESTAMP_TZ,
  ACTION STRING,
  SUBJECT STRING,
  APPROVED_BY STRING,
  SNOWFLAKE_USER STRING,
  IDENTITY_SOURCE STRING,
  BUILD_SHA256 STRING,
  DETAIL VARIANT
) COMMENT = 'A person''s decision (apply or remove a fix, bind a table, switch the data model, deploy), written when they click';

CREATE TABLE IF NOT EXISTS WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.FIXES (
  RUN_ID STRING,
  FIX_ID STRING,
  RECORDED_AT TIMESTAMP_TZ,
  APPROVAL_ID STRING,
  SHEET STRING,
  ACTION STRING,
  QUERY_FIX STRING,
  FIX_KEY STRING,
  PROOF_KEY STRING,
  PROPOSED_BY STRING,
  BUILD_SHA256_AFTER STRING,
  DETAIL VARIANT
) COMMENT = 'A proven fix applied to or removed from a sheet, linked to its approval and proof';

CREATE TABLE IF NOT EXISTS WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.DEPLOYMENTS (
  RUN_ID STRING,
  DEPLOY_ID STRING,
  DEPLOYED_AT TIMESTAMP_TZ,
  APPROVAL_ID STRING,
  APP_IDENTIFIER STRING,
  BUILD_SHA256 STRING,
  FILES NUMBER,
  LOCATION STRING,
  URL STRING,
  RESULT STRING,
  ERROR_CLASS STRING
) COMMENT = 'One row per deploy attempt, linked to its approval';

-- Release 20a/21a: shared Semantic View registry (SL02) and workbook data loads.

CREATE TABLE IF NOT EXISTS WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.SEMANTIC_VIEW_EVENTS (
  RUN_ID STRING,
  RECORDED_AT TIMESTAMP_TZ,
  RECORDED_BY STRING,
  VIEW_NAME STRING,
  BASE_NAME STRING,
  KIND STRING,
  ACTION STRING,
  VERIFIED BOOLEAN,
  OWNER_ROLE STRING,
  DATASOURCE STRING,
  WORKBOOK_NAME STRING,
  TABLES VARIANT,
  BLOCKED VARIANT
) COMMENT = 'Shared Semantic View decisions: reused, refreshed or created, by which run, workbook and datasource, with any view that could not be used and why';

CREATE TABLE IF NOT EXISTS WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.DATA_LOADS (
  RUN_ID STRING,
  RECORDED_AT TIMESTAMP_TZ,
  RECORDED_BY STRING,
  VIA STRING,
  APPROVAL_ID STRING,
  DATASOURCE STRING,
  WORKBOOK_NAME STRING,
  TABLE_NAME STRING,
  SOURCE_FILES VARIANT,
  SOURCE_SHA256 STRING,
  ROWS_LOADED NUMBER,
  COLUMNS NUMBER,
  RESULT STRING
) COMMENT = 'Workbook data loaded into Snowflake: datasource, source files and fingerprint, target table, rows, who approved, and whether it came from the hosted app or the laptop loader';

CREATE TABLE IF NOT EXISTS WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.HIDDEN_RUNS (
  RUN_ID STRING,
  HIDDEN_AT TIMESTAMP_TZ,
  HIDDEN_BY STRING,
  REASON STRING
) COMMENT = 'Runs removed from the Saved runs list by a person; the run and its evidence are kept';

CREATE OR REPLACE VIEW WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.V_RUN_LATEST COMMENT = 'Each run with its latest saved state' AS
SELECT r.*, s.SNAPSHOT_NO, s.SNAPSHOT_AT AS LAST_SAVED_AT, s.REASON AS LAST_SAVED_FOR, s.STATES, s.FAILED_STAGE
FROM WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.RUNS r
LEFT JOIN (SELECT RUN_ID, SNAPSHOT_NO, SNAPSHOT_AT, REASON, STATES, FAILED_STAGE FROM WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.RUN_SNAPSHOTS
           WHERE PART_NO = 0
           QUALIFY ROW_NUMBER() OVER (PARTITION BY RUN_ID ORDER BY SNAPSHOT_NO DESC) = 1) s
  ON s.RUN_ID = r.RUN_ID;

CREATE OR REPLACE VIEW WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.V_CORTEX_COST_BY_RUN COMMENT = 'Cortex calls, tokens and cost by run, stage and model' AS
SELECT RUN_ID, STAGE, MODEL, COUNT(*) AS CALLS,
       COUNT_IF(STATUS ILIKE 'Completed%') AS COMPLETED, COUNT_IF(STATUS ILIKE 'Failed%') AS FAILED,
       SUM(INPUT_TOKENS) AS INPUT_TOKENS, SUM(OUTPUT_TOKENS) AS OUTPUT_TOKENS,
       SUM(AI_CREDITS) AS AI_CREDITS, SUM(COST_USD) AS COST_USD,
       COUNT_IF(TOKEN_SOURCE ILIKE 'Estimated%') AS ESTIMATED_CALLS
FROM WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.CORTEX_CALLS GROUP BY RUN_ID, STAGE, MODEL;

CREATE OR REPLACE VIEW WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.V_CORTEX_SCORECARD COMMENT = 'Per run and stage: Cortex proposals, how many passed code''s check, how many changed the app (latest ruling per proposal)' AS
WITH latest AS (SELECT * FROM WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.CORTEX_PROPOSALS
                QUALIFY ROW_NUMBER() OVER (PARTITION BY RUN_ID, KIND, SUBJECT ORDER BY PROPOSAL_NO DESC) = 1)
SELECT RUN_ID, STAGE, KIND, COUNT(*) AS PROPOSED,
       COUNT_IF(PASSED_CODE_CHECK) AS PASSED_CODE_CHECK,
       COUNT_IF(PASSED_CODE_CHECK = FALSE) AS FAILED_CODE_CHECK,
       COUNT_IF(PASSED_CODE_CHECK IS NULL) AS ADVISORY_OR_NOT_CHECKED,
       COUNT_IF(CHANGES_APP) AS CHANGED_APP
FROM latest GROUP BY RUN_ID, STAGE, KIND;

CREATE OR REPLACE VIEW WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.V_SHEET_LATEST COMMENT = 'Latest draw result and latest Tableau comparison for every sheet of every run' AS
WITH d AS (SELECT * FROM WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.SHEET_RENDERS
           QUALIFY ROW_NUMBER() OVER (PARTITION BY RUN_ID, DASHBOARD, SHEET ORDER BY PASS_NO DESC) = 1),
     c AS (SELECT * FROM WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.SHEET_RESULTS
           QUALIFY ROW_NUMBER() OVER (PARTITION BY RUN_ID, SHEET ORDER BY PASS_NO DESC) = 1)
SELECT r.RUN_ID, r.WORKBOOK_NAME, r.STARTED_AT, d.DASHBOARD, d.SHEET, d.KIND, d.ENGINE_STATE, d.RENDERS,
       d.ROWS_DRAWN, d.NOTE, c.STATUS AS TABLEAU_COMPARISON, c.MATCHED_VALUES, c.MISMATCHED_VALUES
FROM WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.RUNS r
JOIN d ON d.RUN_ID = r.RUN_ID
LEFT JOIN c ON c.RUN_ID = d.RUN_ID AND c.SHEET = d.SHEET;

CREATE OR REPLACE VIEW WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.V_FAILURES COMMENT = 'Every failed stage, every sheet that does not draw, and every sheet that differs from Tableau, across all runs (latest result per sheet)' AS
SELECT r.RUN_ID, r.WORKBOOK_NAME, r.STARTED_AT, 'Stage failed' AS FAILURE, e.STAGE AS WHERE_FOUND,
       e.TITLE AS ITEM, e.DETAIL
FROM WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.RUN_EVENTS e JOIN WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.RUNS r ON r.RUN_ID = e.RUN_ID
WHERE e.KIND = 'failed'
UNION ALL
SELECT RUN_ID, WORKBOOK_NAME, STARTED_AT, 'Sheet does not draw', DASHBOARD, SHEET, NOTE
FROM WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.V_SHEET_LATEST WHERE RENDERS = 'Error'
UNION ALL
SELECT RUN_ID, WORKBOOK_NAME, STARTED_AT, 'Differs from Tableau', DASHBOARD, SHEET,
       MISMATCHED_VALUES || ' value(s) differ'
FROM WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.V_SHEET_LATEST WHERE TABLEAU_COMPARISON = 'Difference found';

CREATE OR REPLACE VIEW WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.V_APPROVAL_TRAIL COMMENT = 'Who approved what and when, with the fix or deployment it led to' AS
SELECT a.RUN_ID, r.WORKBOOK_NAME, a.APPROVED_AT, a.APPROVED_BY, a.SNOWFLAKE_USER, a.IDENTITY_SOURCE,
       a.ACTION, a.SUBJECT, a.BUILD_SHA256, f.FIX_ID, f.QUERY_FIX, f.FIX_KEY, f.PROPOSED_BY, f.PROOF_KEY,
       d.DEPLOY_ID, d.APP_IDENTIFIER, d.RESULT AS DEPLOY_RESULT
FROM WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.APPROVALS a
JOIN WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.RUNS r ON r.RUN_ID = a.RUN_ID
LEFT JOIN WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.FIXES f ON f.APPROVAL_ID = a.APPROVAL_ID
LEFT JOIN WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.DEPLOYMENTS d ON d.APPROVAL_ID = a.APPROVAL_ID;

CREATE OR REPLACE VIEW WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.V_SEMANTIC_VIEW_REGISTRY COMMENT = 'One row per shared Semantic View: tables, last decision, owner and how many workbooks and datasources use it' AS
SELECT VIEW_NAME, BASE_NAME, KIND, ANY_VALUE(TABLES) AS TABLES,
       MAX_BY(ACTION, RECORDED_AT) AS LAST_ACTION, MAX_BY(OWNER_ROLE, RECORDED_AT) AS OWNER_ROLE,
       MIN(RECORDED_AT) AS FIRST_SEEN, MAX(RECORDED_AT) AS LAST_USED,
       COUNT(DISTINCT WORKBOOK_NAME) AS WORKBOOKS, COUNT(DISTINCT DATASOURCE) AS DATASOURCES,
       COUNT_IF(ACTION = 'reused') AS REUSES, ARRAY_AGG(DISTINCT WORKBOOK_NAME) AS WORKBOOK_NAMES
FROM WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.SEMANTIC_VIEW_EVENTS WHERE VERIFIED
GROUP BY VIEW_NAME, BASE_NAME, KIND;

-- Release 20b: estate catalogue (SL01). Harvests only INSERT; the views show the latest complete harvest of each workbook.

CREATE TABLE IF NOT EXISTS WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.CAT_HARVESTS (
  HARVEST_ID STRING,
  RECORDED_AT TIMESTAMP_TZ,
  STATUS STRING,
  STARTED_BY STRING,
  VIA STRING,
  SCOPE STRING,
  SITE STRING,
  CATALOG_VERSION STRING,
  WORKBOOKS_FOUND NUMBER,
  HARVESTED NUMBER,
  UNCHANGED NUMBER,
  FAILED NUMBER,
  METRICS_DESCRIBED NUMBER,
  CORTEX_CALLS NUMBER,
  NOTE STRING
) COMMENT = 'One row when a harvest starts and one when it finishes';

CREATE TABLE IF NOT EXISTS WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.CAT_WORKBOOKS (
  HARVEST_ID STRING,
  RECORDED_AT TIMESTAMP_TZ,
  WORKBOOK_KEY STRING,
  WORKBOOK_NAME STRING,
  SCOPE STRING,
  PROJECT STRING,
  ORIGIN STRING,
  SITE STRING,
  SOURCE_REF VARIANT,
  STATUS STRING,
  CATALOG_VERSION STRING,
  WORKBOOK_SHA256 STRING,
  TABLEAU_VERSION STRING,
  DATASOURCES NUMBER,
  WORKSHEETS NUMBER,
  DASHBOARDS NUMBER,
  CALCULATIONS NUMBER,
  METRICS NUMBER,
  PARAMETERS NUMBER,
  TOTAL_VIEWS NUMBER,
  ERROR_CLASS STRING,
  NOTE STRING
) COMMENT = 'One row per workbook per harvest; written after its detail rows, so a workbook row means its catalogue is complete';

CREATE TABLE IF NOT EXISTS WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.CAT_DATASOURCES (
  HARVEST_ID STRING,
  WORKBOOK_KEY STRING,
  DATASOURCE_ID STRING,
  DATASOURCE STRING,
  CONNECTIONS VARIANT,
  SHAPE STRING,
  TABLES VARIANT,
  SOURCE_KEY STRING,
  HAS_EXTRACT BOOLEAN,
  BLENDED_WITH VARIANT,
  ROUTE STRING,
  ROUTE_REASON STRING,
  FIELDS NUMBER,
  CALCULATIONS NUMBER
) COMMENT = 'Datasources with their shape, source key and the route a migration run takes';

CREATE TABLE IF NOT EXISTS WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.CAT_FIELDS (
  HARVEST_ID STRING,
  WORKBOOK_KEY STRING,
  DATASOURCE_ID STRING,
  FIELD STRING,
  CAPTION STRING,
  PHYSICAL STRING,
  DATATYPE STRING,
  ROLE STRING
) COMMENT = 'Source fields (not calculations) per datasource';

CREATE TABLE IF NOT EXISTS WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.CAT_CALCULATIONS (
  HARVEST_ID STRING,
  WORKBOOK_KEY STRING,
  DATASOURCE_ID STRING,
  DATASOURCE STRING,
  FIELD STRING,
  CAPTION STRING,
  KIND STRING,
  FORMULA STRING,
  NORMALISED STRING,
  FORMULA_FP STRING,
  DEPENDS_ON VARIANT,
  PARAMETERS VARIANT,
  DATATYPE STRING,
  ROLE STRING,
  TRANSLATED_SQL STRING,
  TRANSLATION STRING
) COMMENT = 'Calculations: original formula, normalised formula and fingerprint, kind, dependencies and the translated SQL';

CREATE TABLE IF NOT EXISTS WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.CAT_METRICS (
  HARVEST_ID STRING,
  WORKBOOK_KEY STRING,
  METRIC_FP STRING,
  NAME STRING,
  ORIGIN_KIND STRING,
  KIND STRING,
  EXPRESSION STRING,
  NORMALISED STRING,
  DATASOURCE_ID STRING,
  DATASOURCE STRING,
  SOURCE_KEY STRING,
  FIELD STRING
) COMMENT = 'Metrics per workbook: aggregating calculations and the measures sheets aggregate';

CREATE TABLE IF NOT EXISTS WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.CAT_USAGE (
  HARVEST_ID STRING,
  WORKBOOK_KEY STRING,
  WORKSHEET STRING,
  DASHBOARDS VARIANT,
  DATASOURCE_ID STRING,
  FIELD STRING,
  CAPTION STRING,
  SHELF STRING,
  AGGREGATION STRING,
  IS_MEASURE BOOLEAN,
  METRIC_FP STRING,
  FILTER_CLASS STRING
) COMMENT = 'Which worksheet uses which field or metric, on which shelf, with which aggregation; filters are rows on the filter shelf';

CREATE TABLE IF NOT EXISTS WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.CAT_BINDINGS (
  HARVEST_ID STRING,
  WORKBOOK_KEY STRING,
  DATASOURCE_ID STRING,
  KIND STRING,
  RELATION STRING,
  COLUMNS VARIANT
) COMMENT = 'The Snowflake relation a migration run would read for a datasource (one table, or the code-built relationship query), with its columns; release 22 tests metrics on it';

CREATE TABLE IF NOT EXISTS WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.CAT_VIEWS (
  HARVEST_ID STRING,
  RECORDED_AT TIMESTAMP_TZ,
  WORKBOOK_KEY STRING,
  VIEW_ID STRING,
  VIEW_NAME STRING,
  CONTENT_URL STRING,
  TOTAL_VIEWS NUMBER
) COMMENT = 'Published Tableau views with their total view count (Tableau REST usage statistics)';

CREATE TABLE IF NOT EXISTS WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.CAT_METRIC_DESCRIPTIONS (
  METRIC_FP STRING,
  RECORDED_AT TIMESTAMP_TZ,
  HARVEST_ID STRING,
  BUSINESS_NAME STRING,
  DESCRIPTION STRING,
  INTENT STRING,
  MODEL STRING,
  PROMPT_SHA256 STRING,
  PASSED_CODE_CHECK BOOLEAN,
  CODE_CHECK STRING
) COMMENT = 'Cortex''s business name, description and intent per metric fingerprint, with code''s check; only rows that passed are shown';

CREATE OR REPLACE VIEW WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.V_CAT_WORKBOOKS COMMENT = 'Each workbook''s current catalogue (its latest complete harvest), last time seen and latest view count' AS
WITH h AS (SELECT * FROM WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.CAT_WORKBOOKS WHERE STATUS = 'harvested'
           QUALIFY ROW_NUMBER() OVER (PARTITION BY WORKBOOK_KEY ORDER BY RECORDED_AT DESC) = 1),
     seen AS (SELECT WORKBOOK_KEY, MAX(RECORDED_AT) AS LAST_SEEN, MAX_BY(TOTAL_VIEWS, RECORDED_AT) AS TOTAL_VIEWS,
                     MAX_BY(SCOPE, RECORDED_AT) AS SCOPE, MAX_BY(PROJECT, RECORDED_AT) AS PROJECT,
                     MAX_BY(WORKBOOK_NAME, RECORDED_AT) AS WORKBOOK_NAME
              FROM WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.CAT_WORKBOOKS WHERE STATUS IN ('harvested', 'unchanged') GROUP BY WORKBOOK_KEY)
SELECT h.WORKBOOK_KEY, seen.WORKBOOK_NAME, seen.SCOPE, seen.PROJECT, h.ORIGIN, h.SITE, h.SOURCE_REF, h.HARVEST_ID,
       h.RECORDED_AT AS HARVESTED_AT, seen.LAST_SEEN, h.WORKBOOK_SHA256, h.TABLEAU_VERSION, h.DATASOURCES,
       h.WORKSHEETS, h.DASHBOARDS, h.CALCULATIONS, h.METRICS, h.PARAMETERS, seen.TOTAL_VIEWS, h.NOTE
FROM h JOIN seen ON seen.WORKBOOK_KEY = h.WORKBOOK_KEY;

CREATE OR REPLACE VIEW WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.V_CAT_WORKBOOK_STATUS COMMENT = 'Latest harvest result per workbook, including failures' AS
SELECT * FROM WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.CAT_WORKBOOKS
QUALIFY ROW_NUMBER() OVER (PARTITION BY WORKBOOK_KEY ORDER BY RECORDED_AT DESC) = 1;

CREATE OR REPLACE VIEW WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.V_CAT_DATASOURCES COMMENT = 'Current datasources of every catalogued workbook with their route' AS
SELECT w.SCOPE, w.PROJECT, w.WORKBOOK_NAME, x.* FROM WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.CAT_DATASOURCES x JOIN WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.V_CAT_WORKBOOKS w ON w.WORKBOOK_KEY = x.WORKBOOK_KEY AND w.HARVEST_ID = x.HARVEST_ID;

CREATE OR REPLACE VIEW WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.V_CAT_CALCULATIONS COMMENT = 'Current calculations of every catalogued workbook' AS
SELECT w.SCOPE, w.PROJECT, w.WORKBOOK_NAME, x.* FROM WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.CAT_CALCULATIONS x JOIN WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.V_CAT_WORKBOOKS w ON w.WORKBOOK_KEY = x.WORKBOOK_KEY AND w.HARVEST_ID = x.HARVEST_ID;

CREATE OR REPLACE VIEW WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.V_CAT_METRICS COMMENT = 'Current metrics of every catalogued workbook' AS
SELECT w.SCOPE, w.PROJECT, w.WORKBOOK_NAME, x.* FROM WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.CAT_METRICS x JOIN WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.V_CAT_WORKBOOKS w ON w.WORKBOOK_KEY = x.WORKBOOK_KEY AND w.HARVEST_ID = x.HARVEST_ID;

CREATE OR REPLACE VIEW WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.V_CAT_USAGE COMMENT = 'Current sheet usage of every catalogued workbook' AS
SELECT w.SCOPE, w.PROJECT, w.WORKBOOK_NAME, x.* FROM WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.CAT_USAGE x JOIN WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.V_CAT_WORKBOOKS w ON w.WORKBOOK_KEY = x.WORKBOOK_KEY AND w.HARVEST_ID = x.HARVEST_ID;

CREATE OR REPLACE VIEW WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.V_CAT_FIELDS COMMENT = 'Current source fields of every catalogued workbook' AS
SELECT w.SCOPE, w.PROJECT, w.WORKBOOK_NAME, x.* FROM WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.CAT_FIELDS x JOIN WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.V_CAT_WORKBOOKS w ON w.WORKBOOK_KEY = x.WORKBOOK_KEY AND w.HARVEST_ID = x.HARVEST_ID;

CREATE OR REPLACE VIEW WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.V_CAT_BINDINGS COMMENT = 'Current Snowflake relations of every catalogued datasource' AS
SELECT w.SCOPE, w.PROJECT, w.WORKBOOK_NAME, x.* FROM WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.CAT_BINDINGS x JOIN WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.V_CAT_WORKBOOKS w ON w.WORKBOOK_KEY = x.WORKBOOK_KEY AND w.HARVEST_ID = x.HARVEST_ID;

CREATE OR REPLACE VIEW WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.V_METRIC_CATALOG COMMENT = 'One row per distinct metric (formula fingerprint): its names, workbooks, datasources, sheets and the latest checked Cortex description' AS
WITH u AS (SELECT METRIC_FP, COUNT(DISTINCT WORKBOOK_KEY || '|' || WORKSHEET) AS SHEETS
           FROM WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.V_CAT_USAGE WHERE METRIC_FP IS NOT NULL GROUP BY METRIC_FP),
     d AS (SELECT * FROM WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.CAT_METRIC_DESCRIPTIONS WHERE PASSED_CODE_CHECK
           QUALIFY ROW_NUMBER() OVER (PARTITION BY METRIC_FP ORDER BY RECORDED_AT DESC) = 1)
SELECT m.METRIC_FP, ANY_VALUE(m.KIND) AS KIND, ARRAY_AGG(DISTINCT m.NAME) AS NAMES,
       COUNT(DISTINCT m.NAME) AS NAME_VARIANTS, COUNT(DISTINCT m.WORKBOOK_KEY) AS WORKBOOKS,
       ARRAY_AGG(DISTINCT m.WORKBOOK_NAME) AS WORKBOOK_NAMES, ARRAY_AGG(DISTINCT m.SCOPE) AS SCOPES,
       ARRAY_AGG(DISTINCT m.DATASOURCE) AS DATASOURCES, ANY_VALUE(m.EXPRESSION) AS EXAMPLE_FORMULA,
       ANY_VALUE(m.NORMALISED) AS NORMALISED, COALESCE(ANY_VALUE(u.SHEETS), 0) AS SHEETS,
       ANY_VALUE(d.BUSINESS_NAME) AS BUSINESS_NAME, ANY_VALUE(d.DESCRIPTION) AS DESCRIPTION,
       ANY_VALUE(d.INTENT) AS INTENT, ANY_VALUE(d.MODEL) AS DESCRIBED_BY
FROM WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.V_CAT_METRICS m
LEFT JOIN u ON u.METRIC_FP = m.METRIC_FP
LEFT JOIN d ON d.METRIC_FP = m.METRIC_FP
GROUP BY m.METRIC_FP;

CREATE OR REPLACE VIEW WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.V_METRIC_NAME_VARIANTS COMMENT = 'Calculations with the same name but a different formula (input to release 22; not yet proven to give different numbers)' AS
SELECT UPPER(TRIM(NAME)) AS NAME_KEY, ANY_VALUE(NAME) AS NAME, COUNT(DISTINCT METRIC_FP) AS FORMULAS,
       ARRAY_AGG(DISTINCT EXPRESSION) AS EXPRESSIONS, ARRAY_AGG(DISTINCT WORKBOOK_NAME) AS WORKBOOK_NAMES,
       ARRAY_AGG(DISTINCT SCOPE) AS SCOPES
FROM WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.V_CAT_METRICS WHERE ORIGIN_KIND = 'calculation'
GROUP BY UPPER(TRIM(NAME)) HAVING COUNT(DISTINCT METRIC_FP) > 1;

CREATE OR REPLACE VIEW WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.V_DATASOURCE_ROUTES COMMENT = 'Datasources per scope and route' AS
SELECT SCOPE, ROUTE, COUNT(*) AS DATASOURCES, COUNT(DISTINCT WORKBOOK_KEY) AS WORKBOOKS,
       COUNT(DISTINCT SOURCE_KEY) AS DISTINCT_SOURCES
FROM WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.V_CAT_DATASOURCES GROUP BY SCOPE, ROUTE;

CREATE OR REPLACE VIEW WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.V_ESTATE_SUMMARY COMMENT = 'Per scope: workbooks, views, datasources, calculations, distinct and shared metrics' AS
WITH w AS (SELECT SCOPE, COUNT(*) AS WORKBOOKS, SUM(DATASOURCES) AS DATASOURCES, SUM(WORKSHEETS) AS WORKSHEETS,
                  SUM(DASHBOARDS) AS DASHBOARDS, SUM(CALCULATIONS) AS CALCULATIONS, SUM(TOTAL_VIEWS) AS TOTAL_VIEWS,
                  COUNT_IF(COALESCE(TOTAL_VIEWS, 0) = 0) AS WORKBOOKS_WITHOUT_VIEWS
           FROM WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.V_CAT_WORKBOOKS GROUP BY SCOPE),
     m AS (SELECT SCOPE, METRIC_FP, COUNT(DISTINCT WORKBOOK_KEY) AS N FROM WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.V_CAT_METRICS GROUP BY SCOPE, METRIC_FP),
     ms AS (SELECT SCOPE, COUNT(*) AS DISTINCT_METRICS, COUNT_IF(N > 1) AS SHARED_METRICS FROM m GROUP BY SCOPE),
     r AS (SELECT SCOPE, COUNT_IF(ROUTE IN ('bind_snowflake', 'bind_model', 'load', 'laptop')) AS DATASOURCES_WITH_ROUTE
           FROM WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.V_CAT_DATASOURCES GROUP BY SCOPE)
SELECT w.*, ms.DISTINCT_METRICS, ms.SHARED_METRICS, r.DATASOURCES_WITH_ROUTE
FROM w LEFT JOIN ms ON ms.SCOPE = w.SCOPE LEFT JOIN r ON r.SCOPE = w.SCOPE;

CREATE OR REPLACE VIEW WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.V_CAT_VIEW_USAGE COMMENT = 'Latest view count per published Tableau view' AS
SELECT * FROM WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.CAT_VIEWS
QUALIFY ROW_NUMBER() OVER (PARTITION BY WORKBOOK_KEY, VIEW_ID ORDER BY RECORDED_AT DESC) = 1;

-- Release 22a: rationalisation report (SL03). Runs only INSERT.

CREATE TABLE IF NOT EXISTS WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.RAT_RUNS (
  RUN_ID STRING,
  RECORDED_AT TIMESTAMP_TZ,
  STATUS STRING,
  SCOPE STRING,
  STARTED_BY STRING,
  VIA STRING,
  METRICS NUMBER,
  GROUPS_COMPARED NUMBER,
  TESTED NUMBER,
  COUNTS VARIANT,
  CORTEX_CALLS NUMBER,
  NOTE STRING
) COMMENT = 'One row when a rationalisation run starts and one when it finishes';

CREATE TABLE IF NOT EXISTS WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.RAT_GROUPS (
  RUN_ID STRING,
  RECORDED_AT TIMESTAMP_TZ,
  SCOPE STRING,
  GROUP_ID STRING,
  SOURCE STRING,
  NAME STRING,
  MEMBERS VARIANT,
  VERDICT STRING,
  REASON STRING,
  RELATION STRING,
  GRAINS VARIANT,
  CLUSTERS VARIANT,
  DIFFERENCES VARIANT,
  TESTED_SQL STRING,
  CORTEX_REASON STRING,
  EXPLANATION STRING,
  RECOMMENDED_FP STRING,
  CORTEX_PASSED_CHECK BOOLEAN,
  CODE_CHECK STRING
) COMMENT = 'Groups compared: members, where they were run, the values that differ, verdict, and the checked Cortex explanation and recommendation';

CREATE TABLE IF NOT EXISTS WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.RAT_METRICS (
  RUN_ID STRING,
  RECORDED_AT TIMESTAMP_TZ,
  SCOPE STRING,
  METRIC_FP STRING,
  NAME STRING,
  NAMES VARIANT,
  KIND STRING,
  CLASS STRING,
  GROUP_ID STRING,
  REASON STRING,
  WORKBOOKS NUMBER,
  WORKBOOK_NAMES VARIANT,
  SHEETS NUMBER,
  TABLEAU_VIEWS NUMBER,
  EXPRESSION STRING
) COMMENT = 'Every metric of a scope with its one class and the evidence behind it';

CREATE OR REPLACE VIEW WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.V_RATIONALISATION COMMENT = 'Latest finished rationalisation per scope: every metric with its class' AS
SELECT * FROM WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.RAT_METRICS WHERE RUN_ID IN (SELECT RUN_ID FROM WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.RAT_RUNS WHERE STATUS = 'finished'
QUALIFY ROW_NUMBER() OVER (PARTITION BY SCOPE ORDER BY RECORDED_AT DESC) = 1);

CREATE OR REPLACE VIEW WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.V_RAT_GROUPS COMMENT = 'Latest finished rationalisation per scope: groups compared and their verdicts' AS
SELECT * FROM WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.RAT_GROUPS WHERE RUN_ID IN (SELECT RUN_ID FROM WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.RAT_RUNS WHERE STATUS = 'finished'
QUALIFY ROW_NUMBER() OVER (PARTITION BY SCOPE ORDER BY RECORDED_AT DESC) = 1);

CREATE OR REPLACE VIEW WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.V_RAT_SUMMARY COMMENT = 'Latest finished rationalisation per scope: metrics per class' AS
SELECT SCOPE, CLASS, COUNT(*) AS METRICS FROM WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.RAT_METRICS WHERE RUN_ID IN (SELECT RUN_ID FROM WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE.RAT_RUNS WHERE STATUS = 'finished'
QUALIFY ROW_NUMBER() OVER (PARTITION BY SCOPE ORDER BY RECORDED_AT DESC) = 1)
GROUP BY SCOPE, CLASS;

SHOW TABLES IN SCHEMA WBR_DB.TABLEAU_ACCELERATOR_V3_EVIDENCE;
